/**
 * Lowres Gemstone Interference - Ultra Light Edition
 * A high-performance, glittering 2D animation with dynamic time-scaling.
 */

const RES = 30; // Set the grid resolution (pixel size)
let t = 0; // Initialize global time for color and noise cycles
let movingPhase = 0; // Initialize a phase variable for the wave movement

function setup() {
  pixelDensity(1); // Force standard resolution to save CPU power on high-DPI screens
  createCanvas(windowWidth, windowHeight); // Create a canvas that fills the window
  colorMode(HSB, 360, 100, 100, 1); // Use HSB for intuitive control over vibrant colors
  noStroke(); // Disable outlines to speed up rendering and look cleaner
  rectMode(CENTER); // Draw rectangles from the center for scaling effects
}

function draw() {
  background(240, 80, 5); // Use a deep dark navy for a high-contrast background

  // --- Dynamic Speed Logic ---
  let speedMult = cos(t * 0.4); // Oscillate speed between 1.0, 0.0, and -1.0
  movingPhase += 0.07 * speedMult; // Accumulate the movement phase based on the current speed

  // --- Optimization: Pre-calculate values used in the loop ---
  let t30 = t * 30; // Pre-calculate time-based hue shift
  let t05 = t * 0.5; // Pre-calculate time-based pseudo-noise shift

  // --- Grid Loop ---
  for (let x = RES / 2; x <= width + RES; x += RES) { // Loop through columns
    for (let y = RES / 2; y <= height + RES; y += RES) { // Loop through rows

      // 1. Interference Pattern (Replacing heavy noise with fast trig)
      let valA = sin(x * 0.015 + y * 0.0015 + movingPhase); // First diagonal wave
      let valB = cos(x * 0.0015 - y * 0.015 + movingPhase); // Second perpendicular wave
      let interference = valA * valB; // Multiply waves to create diamond-shaped patterns

      // 2. Pseudo-Noise for color (Fast alternative to noise() function)
      let pNoise = sin(x * 0.01 + t05) * cos(y * 0.01 - t05); // Create shimmering color variance

      // 3. Color and Brightness Calculation
      let hue = (pNoise * 50 + t30 + interference * 40 + 360) % 360; // Calculate final color hue
      let bri = map(interference, -1, 1, 15, 85); // Map wave intensity to brightness

      // 4. Size and Sparkle Logic
      let s = RES * (0.5 + interference * 0.001); // Scale the rectangle size based on waves
      let sparkle = valA > 0.96 && valB > 0.96; // Identify peak intersection points for flashes

      // 5. Optimized Drawing (No push/pop/rotate/translate for maximum speed)
      if (sparkle) { // If the cell is in a sparkle state
        fill(hue, 20, 100); // Set to a bright, near-white "flash" color
        rect(x, y, s * 1.2, s * 1.2); // Draw a larger rectangle for the flash effect
      } else { // Otherwise, draw the standard gemstone layers
        fill(hue, 70, bri, 0.4); // Set color for the outer glow layer
        rect(x, y, s * 1.2, s * 1.2); // Draw the subtle glow layer
        fill(hue, 80, bri + 10); // Set color for the core gemstone layer
        rect(x, y, s, s); // Draw the sharp core pixel
        fill(hue, 10, 100, 0.5); // Set a bright white-ish color for the highlight
        rect(x, y, s * 0.3, s * 0.3); // Draw a tiny central highlight for "glitter"
      }
    }
  }

  t += 0.02; // Increment global time for the next frame
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight); // Adjust canvas size if the browser window changes
}

